/**
 * Shared behaviour for the email-template subject field.
 *
 * The subject is a QEditor (contenteditable) rather than a QInput, so it holds
 * HTML and takes no validation rules — QEditor has no `rules` prop. Both
 * Create.vue and Edit.vue need the same plain-text handling, so it lives here
 * where it can be tested against a real QEditor.
 */

/** QEditor stores the subject as HTML — decode entities and strip tags. */
export function toPlainText(html: string | null | undefined): string {
  const tempDiv = document.createElement('div');
  tempDiv.innerHTML = html ?? '';
  const decodedText = tempDiv.textContent || tempDiv.innerText || '';

  // Remove any HTML tags just in case
  return decodedText.replace(/<\/?[^>]+(>|$)/g, '');
}

/**
 * Insert the clipboard's plain text at the caret, dropping pasted formatting.
 *
 * `stopPropagation` is load-bearing: QEditor does not set
 * `inheritAttrs: false`, so Vue's attribute fallthrough binds `@paste` to
 * QEditor's root element while QEditor *also* spreads it onto the inner
 * contenteditable. The event fires on the contenteditable and then bubbles to
 * the root, so without this the handler runs twice and `execCommand` inserts
 * the pasted text twice.
 */
export function handleSubjectPaste(evt: ClipboardEvent): void {
  evt.stopPropagation();
  evt.preventDefault();

  const pastedText = evt.clipboardData?.getData('text/plain') || '';
  if (!pastedText) {
    return;
  }

  document.execCommand('insertText', false, pastedText);
}
